{"operationName":"ProductCatalog","variables":{"input":{"contextFilter":{"brands":["18370"],"priceType":"FULL","categories":["141258"]},"filter":{},"negativeFilter":{},"sortFilter":{"option":"RANKING","order":"ASC"}},"first":96,"isDesktop":true,"isMobile":false,"facetTypes":["SHIPPING_LOCATIONS","CATEGORIES","BRANDS","DISCOUNT_RANGES","PRICE_RANGES","PROMOTION_OFFERS","SIZES","ATTRIBUTES","COLORS","DELIVERY_METHODS","SUSTAINABILITY_OPTIONS"],"includeRecommendedFacets":true,"includeEdges":false,"includeSortFacets":false,"includeFacets":false,"includeTotalCount":false,"includePageInfo":false},"query":"query ProductCatalog($input: ProductCatalogSearchInput!, $first: Int, $after: String, $last: Int, $before: String, $facetTypes: [ProductCatalogFacetType!], $includeRecommendedFacets: Boolean!, $includeEdges: Boolean!, $includeSortFacets: Boolean!, $includeFacets: Boolean!, $includeTotalCount: Boolean!, $includePageInfo: Boolean!, $isDesktop: Boolean!, $isMobile: Boolean!) {
  productCatalog(
    input: $input
    first: $first
    after: $after
    last: $last
    before: $before
  ) {
    ... on ProductCatalogConnection {
      recommendedFacets(facetTypes: [CATEGORIES, BRANDS]) @include(if: $includeRecommendedFacets) {
        ...ProductCatalogRecommendedFacetFragment
        __typename
      }
      edges @include(if: $includeEdges) {
        cursor
        node {
          ...ProductCatalogItemFragment
          images {
            order
            size480 @include(if: $isDesktop) {
              url
              alt
              __typename
            }
            size300 @include(if: $isMobile) {
              url
              alt
              __typename
            }
            __typename
          }
          __typename
        }
        __typename
      }
      sortFacets @include(if: $includeSortFacets) {
        option
        order
        description
        __typename
      }
      facets(facetTypes: $facetTypes) @include(if: $includeFacets) {
        ...ProductCatalogFacetFragment
        __typename
      }
      totalCount @include(if: $includeTotalCount)
      pageInfo @include(if: $includePageInfo) {
        hasPreviousPage
        hasNextPage
        startCursor
        endCursor
        __typename
      }
      __typename
    }
    ... on InvalidPaginationError {
      message
      __typename
    }
    ... on UnsupportedInputFilterError {
      message
      filters
      __typename
    }
    ... on InvalidRangeFilterError {
      message
      filter
      __typename
    }
    ... on Error {
      message
      __typename
    }
    __typename
  }
}

